import {createReportsUI} from './reports-ui.js';
import {createMoneyHistoryUI} from './money-history-ui.js';
import {createCorrectionUI} from './correction-ui.js';
import {debtRemaining,receiptPaid,receiptRemaining,pendingStockReviews,movementLabel,saleByKey,saleKey} from './business-read.js';
export function createWorkspaceUI(env){
  const {state,go,render,perform,notify,uuid,esc,money,icon,btn,empty,productIdentity,accountName,dateStamp,dateTime,doc,formData,commit,returnToPayment}=env;
  Object.assign(state,{workspaceDraft:null,workspaceFocusId:null,workspaceSearch:'',workspaceFiltersOpen:false,workspaceMoneyKind:'all',workspaceMoneyFrom:'',workspaceMoneyTo:'',creditShare:'',reportPeriod:'today',reportMonth:new Date(Date.now()-11*3600000).toISOString().slice(0,7),reportFrom:'',reportTo:''});
  const accountSelect=(name,label,selected,bankOnly=false)=>`<label>${label}<select name="${name}">${(bankOnly?['brubank','mp','nx']:['cash','brubank','mp','nx']).map(id=>`<option value="${id}" ${selected===id?'selected':''}>${accountName(id)}</option>`).join('')}</select></label>`;
  const titles={inventory:'Inventario',opening:'Stock inicial',openingReview:'Revisar stock inicial',inventoryCount:'Contar producto',stockHistory:'Cambios de stock',stockOperation:'Registro de stock',reviews:'Revisar diferencias',reviewDetail:'Diferencia',debts:'Fiados',debtDetail:'Fiado',debtPayment:'Registrar abono',receiptPayment:'Pagar mercadería',partialCredit:'Una parte fiada',correctionChoice:'Corregir venta',correctionForm:'Corregir venta',correctionReview:'Revisar corrección',correctionDetail:'Corrección',reports:'Reportes',reportGoal:'Meta mensual',reportPrint:'Informe mensual'};
  const flowPages=['opening','openingReview','inventoryCount','stockOperation','reviewDetail','debtPayment','receiptPayment','partialCredit','correctionChoice','correctionForm','correctionReview','correctionDetail','reportGoal','reportPrint'];
  const product=id=>state.products.find(p=>p.id===id);
  const draft=()=>state.workspaceDraft;
  const value=v=>esc(v??'');
  const context=p=>`<div class="workflow-context"><strong>${esc(p.name)}</strong><span>${esc(productIdentity(p))}</span></div>`;
  const field=(label,name,v,attrs='')=>`<label>${label}<input class="customer-input" name="${name}" value="${value(v)}" ${attrs}></label>`;
  const amount=(label,name,v,required=true)=>field(label,name,v,`type="number" inputmode="numeric" min="${required?1:0}" max="999999999" step="1" ${required?'required':''}`);
  const form=html=>`<form id="workspace-form" class="product-form workflow-form">${html}<p id="workspace-error" class="error" role="alert"></p></form>`;
  const summary=(rows)=>`<dl class="workflow-summary">${rows.map(([label,v])=>`<div><dt>${label}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
  const search=(label='Buscar producto')=>`<label class="search">${icon('search')}<input id="workspace-search" type="search" aria-label="${label}" placeholder="${label}" value="${value(state.workspaceSearch)}"></label>`;
  const row=(action,id,title,detail,end='')=>`<button class="menu-row workflow-row" data-wf="${action}" data-id="${value(id)}">${icon('box')}<span class="grow"><strong>${title}</strong><span class="meta">${detail}</span></span>${end?`<b>${end}</b>`:icon('chevron')}</button>`;
  const matches=p=>(p.name+' '+productIdentity(p)).toLocaleLowerCase('es').includes(state.workspaceSearch.toLocaleLowerCase('es'));
  const eligible=p=>!state.lots.some(l=>l.productId===p.id)&&!state.sales.some(s=>s.items.some(i=>i.id===p.id));
  function start(kind,values,page,focus=null){state.workspaceDraft={id:'w_'+uuid(),kind,...values};state.workspaceFocusId=focus;state.workspaceSearch='';go(page);}
  function run(kind,payload){
    const d=draft();if(!d)return;const result=perform(kind,d.id,payload);
    if(result){go(state.page,{replace:true});notify('Registro guardado.');}
    else if(state.operations.find(o=>o.id===d.id)?.status==='failed'){if(state.workspaceDraft)state.workspaceDraft.id='w_'+uuid();render();}
  }
  function inventory(){const reviews=pendingStockReviews(state);return `<div class="workflow-actions">${btn(icon('plus')+'Registrar stock inicial','wf-opening','secondary')}<button class="btn secondary" data-go="stockHistory">${icon('clock')}Cambios de stock</button></div>${reviews.length?`<button class="cash-pending" data-go="reviews">${icon('alert')}<span>${reviews.length} diferencias por revisar</span>${icon('chevron')}</button>`:''}${search()}<div id="workspace-list">${inventoryRows()}</div>`;}
  function inventoryRows(){const ps=state.products.filter(matches);return ps.map(p=>row('count',p.id,esc(p.name),`${esc(productIdentity(p))} · ${p.stock<0?'Diferencia de '+Math.abs(p.stock):p.stock+' registradas'}`,'Contar')).join('')||empty('Sin productos','Agregá un producto al catálogo para empezar.','box');}
  function opening(){const d=draft();if(!d)return inventory();return `<p class="caption">Lo que ya tenías antes de usar Mora. No registra una compra ni mueve dinero.</p>${d.items.length?form(d.items.map(i=>{const p=product(i.productId);return `<section class="workflow-section">${context(p)}<button type="button" class="text-btn" data-wf="remove-opening" data-id="${p.id}">Quitar</button>${amount('Unidades físicas','qty_'+p.id,i.qty)}<label class="workflow-check"><input type="checkbox" name="known_${p.id}" ${i.known?'checked':''}>Conozco el costo</label>${i.known?amount('Costo total de estas unidades ($)','cost_'+p.id,i.totalCost):'<p class="caption">Queda pendiente identificar su costo.</p>'}</section>`;}).join('')):''}${search('Buscar para stock inicial')}<div id="workspace-list">${openingRows()}</div>`;}
  function openingRows(){return state.products.filter(p=>p.active!==false&&eligible(p)&&!draft().items.some(i=>i.productId===p.id)&&matches(p)).map(p=>row('add-opening',p.id,esc(p.name),esc(productIdentity(p)))).join('')||'<p class="caption">Sin otros productos sin movimientos. Para productos con historia usá Contar.</p>';}
  function openingPayload(){const d=draft();if(!d?.items.length)throw Error('Elegí al menos un producto.');return {items:d.items.map(i=>{const qty=Number(i.qty),totalCost=i.known?Number(i.totalCost):null;if(!Number.isSafeInteger(qty)||qty<1||i.known&&(!Number.isSafeInteger(totalCost)||totalCost<1))throw Error('Completá unidades y costos conocidos.');return {productId:i.productId,qty,totalCost};})};}
  function openingReview(){const p=openingPayload();return p.items.map(i=>`<section class="workflow-section">${context(product(i.productId))}${summary([['Unidades',i.qty],['Costo',i.totalCost===null?'Sin informar':money(i.totalCost)]])}</section>`).join('')+'<p class="caption">Se agregan existencias. No se registra dinero, venta ni recepción.</p>';}
  function countPreview(){const d=draft(),p=product(d?.productId);if(!p)return '';const count=Number(d.counted),valid=d.counted!==''&&Number.isSafeInteger(count)&&count>=0,delta=valid?count-d.expectedStock:null,offset=delta===null?0:Math.min(Math.max(0,-d.expectedStock),Math.max(0,delta)),added=delta===null?0:Math.max(0,delta-offset);return summary([['Registradas',d.expectedStock],['Encontradas',valid?count:'—'],['Diferencia',delta===null?'—':delta>0?'+'+delta:delta],...(offset?[['Diferencia anterior regularizada',offset]]:[]),...(added?[['Unidades que se incorporan',added]]:[])]);}
  function countCostFields(){const d=draft(),added=Math.max(0,Number(d.counted||0)-Math.max(0,d.expectedStock));return `${added?`<label class="workflow-check"><input type="checkbox" name="known" ${d.known?'checked':''}>Conozco el costo de las ${added} unidades incorporadas</label>${d.known?amount('Costo total incorporado ($)','totalCost',d.totalCost):'<p class="caption">El costo queda sin informar.</p>'}`:''}`;}
  function countView(){const d=draft(),p=product(d?.productId);if(!p)return inventory();const added=Math.max(0,Number(d.counted||0)-Math.max(0,d.expectedStock));return `${context(p)}<div id="workspace-preview">${countPreview()}</div>${form(`${amount('¿Cuántas unidades encontraste?','counted',d.counted,false)}<label>Motivo<select name="reasonKind"><option value="count" ${d.reasonKind==='count'?'selected':''}>Conteo físico</option><option value="loss" ${d.reasonKind==='loss'?'selected':''}>Rotura o pérdida</option></select></label>${field('Detalle del motivo','reason',d.reason,'required maxlength="200" autocomplete="off"')}<div id="workspace-count-cost">${countCostFields()}</div><p class="caption">Este registro ajusta existencias. No genera una venta ni mueve dinero.</p>`)}`;}
  function stockHistory(){const records=[...state.stockOpenings.map(v=>({...v,kind:'opening'})),...state.inventoryAdjustments.map(v=>({...v,kind:'adjustment'}))].sort((a,b)=>b.at.localeCompare(a.at));return records.map(v=>row('stock-record',v.id,v.kind==='opening'?'Stock inicial':esc(product(v.productId)?.name||'Producto'),`${v.day} · ${dateTime(v.at)}`,v.kind==='opening'?v.items.reduce((n,i)=>n+i.qty,0)+' un.':`${v.delta>0?'+':''}${v.delta} un.`)).join('')||empty('Todavía no hay cambios','Los registros de stock inicial y conteos aparecerán acá.','box');}
  function stockOperation(){const id=state.workspaceFocusId,opening=state.stockOpenings.find(v=>v.id===id),adjustment=state.inventoryAdjustments.find(v=>v.id===id);if(opening)return `<p class="available">Stock inicial registrado</p>${opening.items.map(i=>`${context(product(i.productId))}${summary([['Unidades incorporadas',i.qty],['Costo',i.totalCost===null?'Sin informar':money(i.totalCost)]])}`).join('')}<p class="caption">${opening.day} · ${dateTime(opening.at)}. Sin efecto sobre dinero ni ventas.</p>`;if(adjustment)return `${context(product(adjustment.productId))}${summary([['Antes',adjustment.before],['Contado',adjustment.counted],['Cambio',adjustment.delta],['Motivo',esc(adjustment.reason)]])}<p class="caption">${adjustment.day} · ${dateTime(adjustment.at)}. Sin movimiento de dinero.</p>`;return empty('Registro no disponible','Volvé a Inventario para consultar el historial.','box');}
  function reviews(){return pendingStockReviews(state).map(r=>row('review',r.id,esc(product(r.productId)?.name||'Producto'),`Venta ${r.saleNumber} · ${r.unknownQty} un. sin costo · ${r.stockShortfall||0} por revisar`)).join('')||empty('Sin diferencias pendientes','Las diferencias que registres al vender aparecerán acá.','check');}
  function reviewDetail(){const r=state.stockReviews.find(v=>v.id===state.workspaceFocusId);if(!r)return reviews();const resolution=state.stockResolutions.find(v=>v.reviewId===r.id),p=product(r.productId),d=draft();return `${context(p)}${summary([['Origen','Venta '+r.saleNumber],['Unidades sin lote',r.missingQty],['Unidades sin costo',r.unknownQty],['Stock registrado ahora',p.stock]])}<button class="text-btn" data-wf="review-sale" data-id="${r.saleNumber}">Ver venta de origen${icon('chevron')}</button>${resolution?`<p class="available">Diferencia resuelta con evidencia</p>${summary([['Motivo',esc(resolution.evidence)],['Cambio de stock',resolution.stockDelta],['Costo identificado',resolution.totalCost===null?'No corresponde':money(resolution.totalCost)]])}`:form(`${field('Evidencia o motivo','evidence',d?.evidence||'','required maxlength="300" placeholder="Ej. Conteo y comprobante verificados"')}${amount('Cambio de stock comprobado','stockDelta',d?.stockDelta??'0',false)}<p class="caption">Para disminuir stock o registrar una pérdida, usá Contar productos. Acá sólo regularizás unidades omitidas comprobadas.</p>${r.unknownQty?amount('Costo total identificado de las unidades pendientes ($)','totalCost',d?.totalCost??''):''}<label class="workflow-check"><input type="checkbox" name="evidenceConfirmed" ${d?.evidenceConfirmed?'checked':''} required>Comprobé la evidencia y el efecto sobre las existencias</label><p class="caption">Si todavía no podés justificarlo, volvé sin confirmar. Una compra nueva no cambia los costos anteriores.</p>`)}`;}
  function debts(){return `${search('Buscar fiado')}<div id="workspace-list">${debtRows()}</div>`;}
  function debtRows(){const ds=state.debts.filter(d=>debtRemaining(state,d.id)>0&&`${d.customer} ${d.saleNumber}`.toLowerCase().includes(state.workspaceSearch.toLowerCase()));return ds.map(d=>row('debt',d.id,esc(d.customer),`Venta ${d.saleNumber} · ${d.day}`,money(debtRemaining(state,d.id)))).join('')||empty('Sin fiados pendientes','Los saldos fiados de las ventas aparecerán acá.','check');}
  function debtDetail(){const debt=state.debts.find(d=>d.id===state.workspaceFocusId);if(!debt)return debts();const balance=debtRemaining(state,debt.id),payments=state.debtPayments.filter(p=>p.debtId===debt.id);return `<section class="checkout-balance"><span class="eyebrow">${esc(debt.customer)}</span><strong class="num">${money(balance)}</strong><p>${balance?'Saldo pendiente':'Fiado saldado'}</p></section>${balance?btn('Registrar abono','wf-debt-pay'):''}<button class="text-btn" data-sale="${debt.saleNumber}">Ver venta ${debt.saleNumber}${icon('chevron')}</button>${summary([['Importe original',money(debt.amount)],['Correcciones del fiado',money(state.debtAdjustments.filter(a=>a.debtId===debt.id).reduce((n,a)=>n+a.amount,0))],['Abonado',money(payments.reduce((n,p)=>n+p.amount,0))]])}${state.debtAdjustments.filter(a=>a.debtId===debt.id).map(a=>`<button class="text-btn" data-correction="detail" data-id="${a.correctionId}">Ver corrección del fiado${icon('chevron')}</button>`).join('')}<div class="section-head"><h2>Abonos</h2></div>${payments.map(p=>`<article class="money-record"><div><strong>${money(p.amount)}</strong><span>${p.day} · ${dateTime(p.at)}</span></div><p>${p.parts.map(part=>accountName(part.account)+' '+money(part.amount)).join(' · ')}</p></article>`).join('')||'<p class="caption">Todavía no registraste abonos.</p>'}`;}
  function paymentFields(d){return `<label>Forma de pago<select name="method"><option value="cash" ${d.method==='cash'?'selected':''}>Efectivo</option><option value="transfer" ${d.method==='transfer'?'selected':''}>Transferencia</option><option value="mixed" ${d.method==='mixed'?'selected':''}>Efectivo y transferencia</option></select></label>${d.method==='mixed'?amount('Parte en efectivo ($)','cashShare',d.cashShare):''}${d.method!=='cash'?`${accountSelect('account','Cuenta de la transferencia',d.account||'brubank',true)}<label class="workflow-check"><input type="checkbox" name="transferVerified" ${d.transferVerified?'checked':''} required>Comprobé que la transferencia se acreditó</label>`:''}`;}
  function debtPayment(){const d=draft(),debt=state.debts.find(v=>v.id===d?.debtId);if(!debt)return debts();return `<div class="workflow-context"><strong>${esc(debt.customer)}</strong><span>Venta ${debt.saleNumber}</span></div>${summary([['Pendiente',money(debtRemaining(state,debt.id))]])}${form(`${amount('Importe del abono ($)','amount',d.amount)}${paymentFields(d)}<p class="caption">No suma otra venta ni vuelve a descontar stock.</p>`)}`;}
  function receiptPayment(){const d=draft(),r=state.receipts.find(v=>v.id===d?.receiptId);if(!r)return empty('Elegí una recepción','Abrila desde Reposición.','box');return `<div class="workflow-context"><strong>${esc(r.supplier)}</strong><span>Recepción ${r.day}</span></div>${summary([['Total recibido',money(r.total)],['Ya pagado',money(receiptPaid(state,r))],['Pendiente',money(receiptRemaining(state,r))]])}${form(`${amount('Pago realizado ($)','amount',d.amount)}${accountSelect('account','Cuenta del pago',d.account||'cash')}<label class="workflow-check"><input type="checkbox" name="paidConfirmed" required ${d.paidConfirmed?'checked':''}>Este pago ya lo realicé</label><p class="caption">Se vincula a esta recepción. No vuelve a ingresar mercadería ni crea un gasto duplicado.</p>`)}`;}
  function partialCredit(){const d=draft();return `<p class="caption">Una parte se cobra ahora y el resto queda fiado, en la misma venta.</p>${summary([['Total de la venta',money(env.saleTotal())]])}${form(`${amount('Importe que queda fiado ($)','amount',d.amount)}${field('¿A nombre de quién?','customer',d.customer,'required maxlength="80"')}<label>Cómo cobrás el resto<select name="method"><option value="cash" ${d.method==='cash'?'selected':''}>Efectivo</option><option value="transfer" ${d.method==='transfer'?'selected':''}>Transferencia</option><option value="mixed" ${d.method==='mixed'?'selected':''}>Efectivo y transferencia</option></select></label>`)}`;}
  function capture(){const f=doc.querySelector('#workspace-form'),d=draft();if(!f||!d)return;const v=formData(f);if(d.kind==='opening'){for(const i of d.items){i.qty=String(v.get('qty_'+i.productId)||'');i.known=v.has('known_'+i.productId);i.totalCost=String(v.get('cost_'+i.productId)||'');}}else{for(const [key,val]of v.entries())if(!['__proto__','constructor','prototype'].includes(key))d[key]=String(val);for(const key of ['known','transferVerified','paidConfirmed','evidenceConfirmed'])d[key]=v.has(key);}}
  function save(){capture();const d=draft(),f=doc.querySelector('#workspace-form');if(f&&!f.reportValidity())return;try{
    if(state.page==='opening'){openingPayload();go('openingReview');return;}
    if(state.page==='openingReview'){run('opening',openingPayload());return;}
    if(state.page==='inventoryCount'){run('inventory-adjustment',{productId:d.productId,counted:Number(d.counted),expectedStock:d.expectedStock,reason:d.reason,reasonKind:d.reasonKind,totalCost:d.known?Number(d.totalCost):null});return;}
    if(state.page==='reviewDetail'){const r=state.stockReviews.find(v=>v.id===state.workspaceFocusId);if(!d.evidenceConfirmed)throw Error('Comprobá la evidencia antes de confirmar.');run('resolve-stock',{reviewId:r.id,evidence:d.evidence,stockDelta:Number(d.stockDelta),totalCost:r.unknownQty?Number(d.totalCost):null});return;}
    if(state.page==='debtPayment'){run('debt-payment',{debtId:d.debtId,amount:Number(d.amount),method:d.method,account:d.account,cashShare:d.cashShare||'',transferVerified:!!d.transferVerified});return;}
    if(state.page==='receiptPayment'){run('receipt-payment',{receiptId:d.receiptId,amount:Number(d.amount),account:d.account,paidConfirmed:!!d.paidConfirmed});return;}
    if(state.page==='partialCredit'){const amount=Number(d.amount);if(!Number.isSafeInteger(amount)||amount<1||amount>=env.saleTotal()||!d.customer?.trim())throw Error('El importe fiado debe ser menor que el total. Completá el nombre.');state.creditShare=String(amount);state.customer=d.customer.trim();state.method=d.method;state.received='';state.transferVerified=false;state.workspaceDraft=null;go('pay',{replace:true});return;}
  }catch(error){const el=doc.querySelector('#workspace-error');if(el)el.textContent=error.message;else notify(error.message);}}
  const screens={inventory,opening,openingReview,inventoryCount:countView,stockHistory,stockOperation,reviews,reviewDetail,debts,debtDetail,debtPayment,receiptPayment,partialCredit};
  function dock(){const rd=reportsUI.dock();if(rd)return rd;const cd=corrections.dock();if(cd)return cd;const page=state.page,labels={opening:'Revisar stock inicial',openingReview:'Confirmar stock inicial',inventoryCount:'Guardar conteo',debtPayment:'Confirmar abono',receiptPayment:'Registrar pago',partialCredit:'Continuar al cobro',reviewDetail:'Confirmar resolución'};if(page==='reviewDetail'&&state.stockResolutions.some(r=>r.reviewId===state.workspaceFocusId))return `<div class="dock">${btn('Volver a Inventario','wf-inventory')}</div>`;if(page==='stockOperation')return `<div class="dock">${btn('Volver a Inventario','wf-inventory')}</div>`;return labels[page]?`<div class="dock movement-dock"><span>${state.demo?'Prueba temporal':'Se guarda en este dispositivo'}</span>${btn(labels[page],'wf-save')}</div>`:'';}
  function handleClick(b){if(reportsUI.click(b))return true;if(corrections.click(b))return true;const action=b.dataset.wf||({'wf-opening':'opening','wf-save':'save','wf-inventory':'inventory','wf-debt-pay':'debt-pay'}[b.dataset.action]);if(!action)return false;const id=b.dataset.id;
    if(action==='opening')start('opening',{items:[]},'opening');
    else if(action==='save')save();
    else if(action==='inventory')go('inventory',{root:true});
    else if(action==='count'){const p=product(id);start('count',{productId:id,expectedStock:p.stock,counted:'',reason:'',reasonKind:'count',known:false,totalCost:''},'inventoryCount',id);}
    else if(action==='add-opening'){capture();draft().items.push({productId:id,qty:'',known:false,totalCost:''});render();}
    else if(action==='remove-opening'){capture();draft().items=draft().items.filter(i=>i.productId!==id);render();}
    else if(action==='stock-record'){state.workspaceFocusId=id;go('stockOperation');}
    else if(action==='review'){start('resolve',{evidence:'',stockDelta:'0',totalCost:'',evidenceConfirmed:false},'reviewDetail',id);}
    else if(action==='review-sale'){state.saleId=id;go('saleDetail');}
    else if(action==='debt'){state.workspaceFocusId=id;go('debtDetail');}
    else if(action==='debt-pay'){const debt=state.debts.find(v=>v.id===state.workspaceFocusId);start('debt-payment',{debtId:debt.id,amount:'',method:'cash',account:'brubank',cashShare:'',transferVerified:false},'debtPayment',debt.id);}
    else if(action==='receipt-pay'){const r=state.receipts.find(v=>v.id===(id||state.receiptId));start('receipt-payment',{receiptId:r.id,amount:String(receiptRemaining(state,r)),account:'cash',paidConfirmed:false},'receiptPayment',r.id);}
    else if(action==='receipt-source'){state.receiptId=id;go('receiptDetail');}
    else if(action==='partial-credit'){start('partial-credit',{amount:state.creditShare||'',customer:state.customer||'',method:state.method==='credit'?'cash':state.method},'partialCredit');}
    return true;
  }
  function onInput(e){corrections.onInput(e);if(e.target.closest?.('#report-goal-form'))state.workspaceDraft.amount=e.target.value;if(e.target.id==='workspace-search'){state.workspaceSearch=e.target.value;const el=doc.querySelector('#workspace-list');if(el)el.innerHTML=state.page==='inventory'?inventoryRows():state.page==='debts'?debtRows():openingRows();return;}if(e.target.closest?.('#workspace-form')){capture();if(state.page==='inventoryCount'){const el=doc.querySelector('#workspace-preview');if(el)el.innerHTML=countPreview();if(e.target.name==='counted'){const cost=doc.querySelector('#workspace-count-cost');if(cost)cost.innerHTML=countCostFields();}}}}
  function onChange(e){reportsUI.change(e);moneyHistory.change(e);corrections.onChange(e);if(e.target.closest?.('#workspace-form')){capture();if(['known','method'].includes(e.target.name)||e.target.name.startsWith('known_')){const y=env.scrollY();render();env.scrollTo(y);}}}
  function submit(e){if(e.target.id==='correction-form'){e.preventDefault();corrections.save();return true;}if(e.target.id==='workspace-form'){e.preventDefault();save();return true;}return false;}
  const corrections=createCorrectionUI(env,{start,run});const reportsUI=createReportsUI(env,{start,run}),moneyHistory=createMoneyHistoryUI(env);Object.assign(screens,corrections.screens,reportsUI.screens,{moneyHistory:moneyHistory.screen});
  return {corrections,titles,flowPages,screens,dock,handleClick,onInput,onChange,submit,save,start,run};
}
